 function end(){clearInterval(sprayTimer);sprayTimer=null;if(vectorErasing){vectorErasing=false;save();changed(c);return;}if(active?.brushSettings?.postCorrection&&!active.brushSettings.continuousSpray)active.points=correctStroke(active.points,active.brushSettings.postCorrection);const wasDrawing=!!cv.dataset.drawing;delete cv.dataset.drawing;if(paintFrame){cancelAnimationFrame(paintFrame);paintFrame=0;}if(ink){ink.finish();ink=null;}else if(active)drawCut(c,cv);if(path&&shape==='fill'){if(path.length>2&&Math.abs(path.reduce((a,p,i)=>{const q=path[(i+1)%path.length];return a+p[0]*q[1]-q[0]*p[1];},0))*cv.width*cv.height>2){checkpoint();const layer=activePaint(c);if(layer&&!layer.locked&&layerVisible(c,layer)){c.strokes.push({...settings(),kind:'fill',layerId:layer.id,mask:!!layer.editMask,alphaLock:!!layer.alphaLock,selectionMask:art.maskFor(c)||c.pixelSelection?.bitmap,points:path});drawCut(c,cv);save();changed(c);}}temp.remove();path=temp=null;}if(active){save();changed(c);}active=pan=shape=null;if(wasDrawing)document.dispatchEvent(new Event('drawing-ended'));}
